function confirmVote(r,accept) {confirmOperation(accept?'批准本次申请':'拒绝本次申请',accept?'确认后计入本人同意票，并按策略流转。不会自动执行密钥操作。':'拒绝后本申请结束，不会继续交给下一人。',async()=>{const out=await api(`/api/requests/${encodeURIComponent(r.id)}/votes`,'POST',{digest:r.digest,accept});closeWork();state.verified.delete(r.id);toast(out.decision==='approved'?'审批门槛已满足，等待原申请人执行。':accept?'本人确认已记录，已转交下一位。':'申请已拒绝。');await refresh();},!accept);}
function confirmSkip(r) {const body=openWork('本人放弃并转交','不计赞成票');body.append(node('p','section-description','只有当前人员可以放弃。若剩余人员不足以达到 M，申请将结束，不会降低门槛。'));const form=node('form','');form.id='skip-form';const label=node('label','','放弃原因');const input=node('textarea');input.name='reason';input.required=true;input.maxLength=256;input.rows=3;label.append(input);form.append(label);body.append(form);formAction(form,'确认放弃并转交',async d=>{await api(`/api/requests/${encodeURIComponent(r.id)}/skip`,'POST',{digest:r.digest,reason:d.get('reason').trim()});closeWork();toast('本人放弃已记录，请查看新的流转状态。');await refresh();});}
let afterMFA=null;
async function startMFA(purpose,after=null) {const epoch=state.epoch,ticket=++state.mfaEpoch;const response=await api('/api/mfa/challenges','POST',{purpose});if(epoch!==state.epoch||ticket!==state.mfaEpoch||!state.session)return;if($('#work-dialog').open)closeWork();afterMFA=after;state.mfa=response.state;$('#mfa-title').textContent=purpose==='management'?'完成本人验证':'验证本次审批';$('#mfa-context').textContent=purpose==='management'?'使用本人已登记的验证方式完成管理验证。':'验证仅用于当前申请，完成后仍需你核对并确认，才会交接给下一人。';notice($('#mfa-error'),'');renderMFA(response);const d=$('#mfa-dialog');if(!d.open)d.showModal();}
function renderMFA(response) {const ticket=state.mfaEpoch;const current=()=>ticket===state.mfaEpoch&&state.mfa?.id===response.state.id&&!!state.session;const m=response.state;state.mfa=m;const passed=new Set(m.verified);const complete=m.completed;$('#mfa-progress').replaceChildren(node('div','mfa-progress',complete?'本人验证已完成，请返回继续确认。':`已完成 ${passed.size} 项绑定验证 · 有效期至 ${date(m.expiresAt)}`));$('#mfa-finish').hidden=!complete;const container=$('#mfa-factors');container.replaceChildren();
 for(const f of m.factors){const card=node('div','mfa-factor'),head=node('div','mfa-factor-head');head.append(icon(f.method),node('h3','',f.label),badge(passed.has(f.id)?'已通过':!response.available[f.method]?'插件未接入':'待验证',passed.has(f.id)?'success':'neutral'));card.append(head);if(complete||passed.has(f.id)||!response.available[f.method]){if(!response.available[f.method])card.append(node('p','','该插件尚未接入，不能计入验证。'));container.append(card);continue;}
 const input=node('input');input.type='password';input.inputMode='numeric';input.autocomplete='one-time-code';input.maxLength=f.method==='totp'?6:8;input.placeholder=f.method==='totp'?'六位动态码':'八位验证码';input.setAttribute('aria-label',f.label+' 验证码');if(f.method!=='hardware')card.append(input);const actions=node('div','mfa-factor-actions');const message=node('p','','先准备验证，再输入本人的验证码。');const base=`/api/mfa/challenges/${encodeURIComponent(m.id)}/factors/${encodeURIComponent(f.id)}`;let hardwareOptions=null;
 const verify=button('核验此方式',async()=>{notice($('#mfa-error'),'');let body={code:input.value};input.value='';if(f.method==='hardware')body={proof:await hardwareAssertion(hardwareOptions)};try{const next=await api(base+'/verify','POST',body);if(!current())return;renderMFA(next);if(next.state.completed){state.verified.set(m.purpose,new Date(m.expiresAt).getTime());await refresh();}}catch(e){if(current())notice($('#mfa-error'),e.message,'danger');throw e;}},'small');verify.disabled=true;
 const prepare=button(f.method==='totp'?'准备动态码验证':f.method==='hardware'?'开始硬件验证':'发送验证码',async()=>{const attempt=await api(base,'POST',{});if(!current())return;hardwareOptions=attempt.options;verify.disabled=false;message.textContent=f.method==='totp'?'请输入验证器当前显示的动态码。':f.method==='hardware'?'请按浏览器提示使用本人的硬件安全密钥。':'验证码已交由插件发送，请在有效期内输入。';},'plain small');actions.append(prepare,verify);card.append(actions,message);container.append(card);}
}
async function hardwareAssertion(options) {if(!options?.publicKey)throw new Error('硬件插件未提供浏览器支持的验证契约，请联系接入人员。');const decode=value=>Uint8Array.from(atob(value.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const encode=value=>btoa(String.fromCharCode(...new Uint8Array(value))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const publicKey=structuredClone(options.publicKey);publicKey.userVerification='required';publicKey.challenge=decode(publicKey.challenge);if(publicKey.allowCredentials)for(const c of publicKey.allowCredentials)c.id=decode(c.id);const assertion=await navigator.credentials.get({publicKey});if(!assertion)throw new Error('硬件验证未完成。');return {id:assertion.id,rawId:encode(assertion.rawId),type:assertion.type,response:{clientDataJSON:encode(assertion.response.clientDataJSON),authenticatorData:encode(assertion.response.authenticatorData),signature:encode(assertion.response.signature),userHandle:assertion.response.userHandle?encode(assertion.response.userHandle):null}};}
function governanceEvidence(form){const reason=node('label','full','变更原因');const input=node('textarea');input.name='reason';input.required=true;input.minLength=3;input.maxLength=500;input.rows=2;reason.append(input);const evidence=node('label','full','身份核验或变更记录 SHA-256');const hash=node('input');hash.name='evidenceHash';hash.required=true;hash.pattern='[0-9a-f]{64}';hash.placeholder='64位小写十六进制摘要';evidence.append(hash);form.append(reason,evidence);}
function governanceOperation(kind,revision,change){return {kind,clientId:'governance-management',expectedRevision:String(revision),name:'',profileId:'',profileVersion:'0',governance:change};}
function openPolicyDraft(){const p=state.settings;const order=[...p.approvers];const body=openWork('申请变更审批策略','以当前策略审批');body.append(node('p','notice','新策略须由当前审批人员依次批准。执行后旧策略下未执行申请失效，不能降低到少于两人。'));const form=node('form','form-grid');form.id='policy-draft';const label=node('label','full','需要同意的人员数量 M');const m=node('input');m.name='m';m.type='number';m.min=2;m.max=32;m.required=true;m.value=p.m;label.append(m);form.append(label);const list=node('div','full');const eligible=p.people.filter(v=>v.enabled&&(v.mfaConfigured||!state.context.identity.mfaRequired)&&v.grants.some(g=>g.role==='approver'&&!g.clientId));
 const render=()=>{list.replaceChildren();order.forEach((id,i)=>{const row=node('div','policy-sort-row');row.append(node('span','',i+1),node('span','',person(id)));const up=button('↑',()=>{[order[i-1],order[i]]=[order[i],order[i-1]];render();},'plain');up.disabled=i===0;up.setAttribute('aria-label','上移 '+person(id));const down=button('↓',()=>{[order[i+1],order[i]]=[order[i],order[i+1]];render();},'plain');down.disabled=i===order.length-1;down.setAttribute('aria-label','下移 '+person(id));row.append(up,down,button('移除',()=>{order.splice(i,1);render();},'plain'));list.append(row);});};render();form.append(list);const select=node('select');select.setAttribute('aria-label','加入审批人员');for(const person of eligible){const option=node('option','',person.personId);option.value=person.principalId;select.append(option);}form.append(select,button('加入名单',()=>{if(select.value&&!order.includes(select.value)){order.push(select.value);render();}}));governanceEvidence(form);body.append(form);const submit=operationSubmitter();formAction(form,'提交策略变更审批',d=>submit(governanceOperation('approval_policy_update',p.version,{enabled:false,m:Number(d.get('m')),approvers:[...order],reason:d.get('reason').trim(),evidenceHash:d.get('evidenceHash').trim()})));}
function openPersonDetail(p){const body=openWork('管理人员详情','本地授权',true);body.append(detailList([['人员标识',p.personId],['身份主键',p.principalId],['身份源',p.issuer],['状态',p.enabled?'已启用':'已停用'],['本人验证',p.mfaConfigured?'已配置':'尚未配置'],['修订',p.revision]]));const list=node('div');body.append(list);table(list,['角色','范围'],p.grants.map(g=>[labels.roles[g.role],g.clientId||'全域']));body.append(node('p','notice','角色使用既有六类模型。新增登录密码、验证器绑定和换绑通过独立受控流程维护。'));$('#dialog-actions').append(button('关闭',closeWork,'plain'));}
function openPersonCreate(){const body=openWork('登记管理人员','身份关联申请');body.append(node('p','notice','登记后不自动创建登录密码，也不授予角色。请使用已接入身份源的准确 issuer/sub，并核验自然人归属；本人验证和授权须分别完成。'));const form=node('form','form-grid');form.id='person-create';for(const [name,title]of [['issuer','OIDC issuer'],['subject','OIDC subject'],['personId','自然人标识']]){const label=node('label',name==='issuer'?'full':'',title),input=node('input');input.name=name;input.required=true;input.maxLength=name==='issuer'?2048:name==='subject'?1024:128;if(name==='issuer')input.value=state.settings.people.find(p=>p.principalId===state.context.identity.principalId)?.issuer||'';if(name==='personId')input.pattern='[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}';label.append(input);form.append(label);}governanceEvidence(form);body.append(form);const submit=operationSubmitter();formAction(form,'提交人员登记审批',d=>submit(governanceOperation('principal_create',0,{issuer:d.get('issuer').trim(),subject:d.get('subject'),personId:d.get('personId').trim(),enabled:true,reason:d.get('reason').trim(),evidenceHash:d.get('evidenceHash').trim()})));}
function openPersonUpdate(p){const body=openWork('调整人员与授权','当前修订 '+p.revision);body.append(node('p','notice','本次申请完整替换此人的启用状态和角色范围；未选角色将被撤销。执行后此人的旧管理验证、旧票和H5会话失效，必须重新认证。本人及同一自然人别名不能发起或审批自己的调整。'));body.append(detailList([['人员',p.personId],['身份主键',p.principalId]]));const form=node('form','form-grid');form.id='person-update';const enabled=node('select');enabled.name='enabled';enabled.setAttribute('aria-label','人员状态');for(const [v,t]of [['true','启用'],['false','停用']]){const option=node('option','',t);option.value=v;enabled.append(option);}enabled.value=String(p.enabled);form.append(enabled);const rows=node('div','full');form.append(rows);const selected=p.grants.map(g=>({...g}));const render=()=>{rows.replaceChildren();table(rows,['角色','范围','操作'],selected.map((g,i)=>[labels.roles[g.role],g.clientId||'全域',button('移除',()=>{selected.splice(i,1);render();},'text-button')]));};render();const role=node('select');role.setAttribute('aria-label','添加角色');for(const [value,title]of Object.entries(labels.roles)){const option=node('option','',title);option.value=value;role.append(option);}const scope=node('input');scope.setAttribute('aria-label','角色范围');scope.placeholder='服务或客户端标识，留空为全域';scope.maxLength=128;form.append(role,scope,button('加入授权',()=>{const grant={role:role.value,clientId:scope.value.trim()};if(!selected.some(g=>g.role===grant.role&&g.clientId===grant.clientId)){selected.push(grant);render();}}));governanceEvidence(form);body.append(form);const submit=operationSubmitter();formAction(form,'提交人员授权审批',d=>submit(governanceOperation('principal_update',p.revision,{target:p.principalId,enabled:d.get('enabled')==='true',grants:selected.map(g=>({...g})),reason:d.get('reason').trim(),evidenceHash:d.get('evidenceHash').trim()})));}
