// 应用信任链只导入公开证书提案，私钥及离线根材料不能通过管理页面上传。
function renderTrust(){
 const data=state.trust;$('#trust-import').disabled=!data||!data.roots?.length||!hasRole('requester')||!state.context?.identity.mfaVerified;
 const summary=$('#trust-root'),target=$('#trust-table');summary.replaceChildren();target.replaceChildren();
 if(!data){empty(target,'应用信任链尚未配置或当前无权查看','配置应用根证书和独立状态签名服务后，才能发布业务证书。');return;}
 const roots=data.roots||[];summary.append(node('p','section-description',`共 ${roots.length} 个独立根，${data.services.length} 个业务服务。每个服务固定绑定一个根，客户端只信任自己预置的根。`));renderTrustReminders(summary);
 // 展开状态只作用于当前身份的页面，退出时清空，不改变证书或审批状态。
 for(const root of roots){
  const services=data.services.filter(s=>s.rootFingerprint===root.fingerprint),epoch=state.epoch;
  const group=node('details','trust-chain');group.dataset.trustRoot=root.fingerprint;group.open=state.trustExpanded.get(root.fingerprint)??true;
  const heading=node('summary');heading.append(node('span','trust-chain-title',`根证书 · ${root.applicationEnvironment}`),node('span','subtle',`${services.length} 个业务服务`));group.append(heading);
  const content=node('div','panel-body');const rootActions=node('div','table-actions');rootActions.append(button('根证书详情',()=>openTrustRoot(root.fingerprint)),button('下载根证书 PEM',()=>downloadTrustCertificate(`/api/trust/roots/${encodeURIComponent(root.fingerprint)}/download?format=pem`,'root-'+root.fingerprint+'.pem')));content.append(detailList([['固定根指纹',root.fingerprint],['根证书到期',root.info?fullDate(root.info.notAfter):'—']]),rootActions);const signer=state.signers?.signers.find(v=>v.rootFingerprint===root.fingerprint);if(signer){content.append(detailList([['状态签名器修订',signer.revision],['状态证书到期',fullDate(signer.info.notAfter)],['状态证书指纹',signer.info.fingerprint],['本节点材料',state.signers.nodeReady[root.fingerprint]?'已加载当前证书':'未加载当前证书，拒绝签发状态']]));if(hasRole('requester'))content.append(button('导入状态证书更新提案',()=>openTrustImport('status')));content.append(button('状态证书变更记录',()=>openStatusHistory(signer)));};group.append(content);target.append(group);
  group.addEventListener('toggle',()=>{if(group.isConnected&&epoch===state.epoch)state.trustExpanded.set(root.fingerprint,group.open);});
  const list=node('div');content.append(list);
  if(!services.length){empty(list,'暂无业务证书','此根已配置；导入该根签发的公开提案，通过多人审批发布业务证书。');continue;}
  table(list,['业务服务','证书版本','状态','到期时间','修订','操作'],services.map(s=>{
   const actions=node('div','table-actions');actions.append(button('详情与历史',()=>openTrustHistory(s.serviceId,s.version),'text-button'));if(!s.disabled&&hasRole('requester'))actions.append(button('申请续期',()=>openTrustImport('renewal',s.serviceId),'text-button'));
   if(!s.disabled&&hasRole('requester',s.serviceId))actions.append(button('申请停用',()=>confirmOperation('停用业务证书',`服务 ${s.serviceId} / v${s.version}，审批执行后不再签发可接受的状态证明。`,()=>submitOperation({kind:'trust_service_disable',clientId:s.serviceId,expectedRevision:String(s.revision),keyVersion:String(s.version),trustRootFingerprint:root.fingerprint})),'text-button'));
   if(!s.disabled&&hasRole('emergency_operator',s.serviceId))actions.append(button('泄露撤销',()=>confirmOperation('撤销业务证书',`撤销 ${s.serviceId} / v${s.version}；该版本不能恢复，后续必须审批发布更高版本。已签发状态最多有效30秒。`,async()=>{await api(`/api/trust/${encodeURIComponent(s.serviceId)}/revoke`,'POST',{version:s.version,reason:'confirmed_leak'});closeWork();toast('业务证书已撤销。');await refresh();},true),'text-button'));
   return[s.serviceId,'v'+s.version,badge(s.disabled?'disabled':'active'),s.info?textCell(fullDate(s.info.notAfter),expiryText(s.info.notAfter)): '—',s.revision,actions];
  }));
 }
 if(!roots.length)empty(target,'暂无可见的根证书','当前账号没有已配置根或其业务服务的查看权限。');
}
function openTrustImport(mode='publish',service=''){const epoch=state.epoch;const kind=mode==='status'?'trust_status_update':mode==='renewal'?'trust_certificate_renew':'trust_certificate_publish';const body=openWork(labels.operations[kind]+' · 导入公开提案','应用信任链');body.append(node('p','notice','提案只包含公开证书和持有证明。变更经过多人审批。续期须延长有效期；状态证书更新前应在所有节点预装新材料，缺失材料的节点会拒绝签发状态。'));const form=node('form','form-grid');form.id='trust-publish';const label=node('label','full','公开发布提案 JSON');const input=node('input');input.type='file';input.accept='.json,application/json';input.required=true;label.append(input);const preview=node('div','full');form.append(label,preview);body.append(form);let operation=null;const submit=operationSubmitter();input.addEventListener('change',async()=>{operation=null;preview.replaceChildren();try{const file=input.files?.[0];if(!file||file.size>32768)throw new Error('请选择32KiB以内的公开提案。');const data=JSON.parse(await file.text());if(epoch!==state.epoch||!form.isConnected)return;const allowed=new Set(['kind','clientId','expectedRevision','keyVersion','name','profileId','profileVersion','trustRootFingerprint','trustCertificate','trustProof']);if(Object.keys(data).some(k=>!allowed.has(k))||data.kind!==kind||(service&&data.clientId!==service)||!state.trust?.roots?.some(root=>root.fingerprint===data.trustRootFingerprint)||typeof data.trustCertificate!=='string'||typeof data.trustProof!=='string')throw new Error('提案格式或固定根不匹配，不能导入。');const cert=Uint8Array.from(atob(data.trustCertificate),c=>c.charCodeAt(0));const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',cert)),b=>b.toString(16).padStart(2,'0')).join('');if(epoch!==state.epoch||!form.isConnected)return;operation=data;preview.append(detailList([['服务标识',data.clientId],['新版本','v'+data.keyVersion],['预期修订',data.expectedRevision],['证书指纹',hash],['固定根指纹',data.trustRootFingerprint]]));}catch(e){if(form.isConnected)preview.append(node('p','notice danger',e.message));}});formAction(form,'提交'+labels.operations[kind]+'审批',()=>{if(!operation)throw new Error('请先导入合法的公开提案。');return submit(operation);});}
$('#trust-import').addEventListener('click',()=>openTrustImport());

const trustValidity={valid:'有效期内',expired:'已过期',not_yet_valid:'尚未生效'};
const trustChangeLabels={published:'发布并启用',retired:'被新版本替代',disabled:'审批停用',revoked:'泄露撤销'};
const trustReasonLabels={approved_renewal:'审批续期',approved_publish:'审批发布',approved_disable:'审批停用',replaced_by_new_version:'新版本替代',confirmed_leak:'确认泄露'};
function certificateFields(info){return detailList([['主体',info.subject],['签发者',info.issuer],['序列号',info.serial],['SHA-256 指纹',info.fingerprint],['公钥算法',info.algorithm],['签名算法',info.signatureAlgorithm],['生效时间',fullDate(info.notBefore)],['到期时间',fullDate(info.notAfter)],['有效期状态',trustValidity[info.validity]||info.validity],['证书类型',info.isCA?'根 CA 证书':'业务签名证书'],['Key Usage',String(info.keyUsage)],['Extended Key Usage',(info.extendedKeyUsage||[]).join(', ')||'—'],['用途绑定 URI',(info.uris||[]).join(' / ')||'—']]);}
// 公开下载仍经服务端实时鉴权；身份或抽屉改变后不再触发本地保存。
async function downloadTrustCertificate(path,name){const epoch=state.epoch,dialogEpoch=state.dialogEpoch;const response=await fetch(path,{credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error(errorMessages[response.status]||'公开证书下载失败。');const blob=await response.blob();if(epoch!==state.epoch||dialogEpoch!==state.dialogEpoch||!state.session)return;const url=URL.createObjectURL(blob),link=node('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function certificateDownloadButtons(target,base,name){target.append(button('下载 PEM',()=>downloadTrustCertificate(base+'/download?format=pem',name+'.pem')),button('下载 DER',()=>downloadTrustCertificate(base+'/download?format=der',name+'.der')));}
async function openTrustRoot(fingerprint){const epoch=state.epoch,body=openWork('根证书详情','公开证书',true),ticket=state.dialogEpoch;body.append(node('p','subtle','正在读取根证书…'));const data=await api('/api/trust/roots/'+encodeURIComponent(fingerprint));if(epoch!==state.epoch||ticket!==state.dialogEpoch||!body.isConnected)return;body.replaceChildren();body.append(detailList([['应用环境',data.root.applicationEnvironment]]),certificateFields(data.info));const actions=node('div','table-actions');certificateDownloadButtons(actions,'/api/trust/roots/'+encodeURIComponent(fingerprint),'root-'+fingerprint);body.append(actions,node('p','notice','这里只下载公开根证书。证书详情不代替客户端固定根与实时状态验证。'));$('#dialog-actions').append(button('关闭',closeWork,'plain'));}
async function openTrustHistory(service,initialVersion){
 const epoch=state.epoch,body=openWork(service+' · 证书详情与历史','应用信任链',true),ticket=state.dialogEpoch;let versionTicket=0,historyTicket=0;
 const current=()=>epoch===state.epoch&&ticket===state.dialogEpoch&&body.isConnected&&$('#work-dialog').open;
 const historyBox=node('div'),historyFooter=node('div','table-actions'),detailBox=node('section','detail-section');body.append(node('h3','','版本历史'),historyBox,historyFooter,detailBox);$('#dialog-actions').append(button('关闭',closeWork,'plain'));let rows=[];
 async function loadVersion(version){const request=++versionTicket;notice($('#dialog-error'),'');detailBox.replaceChildren(node('p','subtle','正在读取 v'+version+'…'));const data=await api(`/api/trust/services/${encodeURIComponent(service)}/certificates/${version}`);if(!current()||request!==versionTicket)return;const cert=data.certificate;detailBox.replaceChildren(node('h3','','业务证书 v'+cert.version));detailBox.append(detailList([['业务服务',service],['应用环境',data.root.applicationEnvironment],['根指纹',data.root.fingerprint],['生命周期',badge(cert.state)],['是否当前版本',cert.current?'是':'否'],['服务是否停用',data.service.disabled?'是':'否'],['签名与用途完整性',data.chainValid?'通过':'不通过']]));detailBox.append(node('p',data.authenticationEligible?'notice':'notice danger',data.authenticationEligible?'符合证书侧条件；实际认证仍须验证实时状态、用途、正文和挑战。':'当前不符合证书侧认证条件；历史证书仅供查阅与公开下载。'),certificateFields(cert.info));const downloads=node('div','table-actions');certificateDownloadButtons(downloads,`/api/trust/services/${encodeURIComponent(service)}/certificates/${version}`,service+'-v'+version);downloads.append(button('查看所属根',()=>openTrustRoot(data.root.fingerprint)));detailBox.append(downloads,node('h3','','变更记录'));const changes=node('div');detailBox.append(changes);if(!data.changes.length)empty(changes,'暂无结构化变更记录','旧数据不补造操作时间或原因，可查看下方关联审批。');else table(changes,['动作','原因','时间','操作人','关联申请'],data.changes.map(change=>[trustChangeLabels[change.action]||change.action,trustReasonLabels[change.reason]||change.reason,fullDate(change.recordedAt),person(change.actorId),change.approvalId?button('查看申请',()=>openRequest(change.approvalId),'text-button'):'应急操作']));if(data.changesHasMore)detailBox.append(node('p','subtle','仅展示最近100条结构化变更。'));detailBox.append(node('h3','','关联审批申请'));const approvals=node('div');detailBox.append(approvals);if(!data.approvals.length)empty(approvals,'暂无关联申请','此版本没有可关联的审批记录。');else table(approvals,['申请','状态','发起时间','操作'],data.approvals.map(a=>[textCell(labels.operations[a.kind]||a.kind,short(a.id)),badge(a.executed?'executed':a.decision),fullDate(a.createdAt),button('查看详情',()=>openRequest(a.id),'text-button')]));if(data.approvalsHasMore)detailBox.append(node('p','subtle','仅展示最近100个关联申请。'));}
 async function loadHistory(before=0){const request=++historyTicket,data=await api(`/api/trust/services/${encodeURIComponent(service)}/certificates?limit=20`+(before?'&before='+before:''));if(!current()||request!==historyTicket)return;rows=before?rows.concat(data.certificates):data.certificates;historyBox.replaceChildren();if(!rows.length)empty(historyBox,'暂无证书版本','刷新后重试。');else table(historyBox,['版本','生命周期','有效期','详情'],rows.map(cert=>[textCell('v'+cert.version,cert.current?'当前版本':'历史版本'),badge(cert.state),textCell(trustValidity[cert.info.validity]||cert.info.validity,fullDate(cert.info.notAfter)),button('查看 v'+cert.version,()=>loadVersion(cert.version),'text-button')]));historyFooter.replaceChildren();if(data.hasMore)historyFooter.append(button('加载更早版本',()=>loadHistory(data.nextBefore)));}
 await Promise.all([loadHistory(),loadVersion(initialVersion)]);
}

// 到期仅作运维提醒，不能以浏览器本地时间代替服务端证书与实时状态校验。
function expiryText(value){const ms=new Date(value)-Date.now();if(ms<=0)return '已过期';if(ms<3600000)return '不足1小时';if(ms<86400000)return '剩余约'+Math.ceil(ms/3600000)+'小时';return '剩余约'+Math.ceil(ms/86400000)+'天';}
function renderTrustReminders(target){
 const data=state.reminders;if(!data){target.append(node('p','subtle','到期提醒仅全域查看者可见。'));return;}
 const box=node('details','trust-chain'),head=node('summary');head.append(node('span','trust-chain-title','到期提醒'),node('span','subtle',data.reminders.filter(v=>!['sent','superseded'].includes(v.state)).length+' 条待发送'));box.append(head);const body=node('div','panel-body');box.append(body);target.append(box);
 body.append(node('p','subtle','每分钟扫描；邮件、短信由固定 HTTPS/mTLS 插件投递。未配置插件时保留待发送，不代表已通知。'));
 const stage={pending:'待发送',sending:'发送中',sent:'插件已确认接收',superseded:'已被替代'},severity={due_7d:'7天内到期',due_24h:'24小时内到期',due_1h:'1小时内到期',expired:'已过期'},kind={root:'应用根',status:'状态签名证书',service:'业务证书'};
 if(data.reminders.length)table(body,['对象','提醒','到期时间','投递','尝试次数'],data.reminders.map(v=>[textCell(v.serviceId||'根证书',kind[v.kind]+' · '+short(v.fingerprint)),severity[v.severity],fullDate(v.expiresAt),stage[v.state],v.attempts]));else body.append(node('p','subtle','暂无到期提醒，首次扫描完成后刷新。'));
 if(data.hasMore)body.append(node('p','notice','当前只显示最近200条提醒。'));
}

function openStatusHistory(signer){const body=openWork('状态证书变更记录','公开元信息',true);body.append(certificateFields(signer.info));const records=node('div');body.append(records);table(records,['修订','指纹','时间','操作人','审批'],signer.changes.map(v=>[v.revision,short(v.fingerprint),fullDate(v.recordedAt),person(v.actorId),v.approvalId?button('查看申请',()=>openRequest(v.approvalId),'text-button'):'首次可信启动登记']));if(signer.changesHasMore)body.append(node('p','subtle','仅展示最近50条变更。'));$('#dialog-actions').append(button('关闭',closeWork,'plain'));}

function openMaintenanceCode(id){const value=state.maintenanceCodes.get(id);if(!value)throw Error('当前页面已不保存交付码，请重新申请。');const body=openWork('本人交付码','敏感恢复凭证');body.append(node('p','notice danger','此码具有账号恢复权限，只能通过组织受控渠道交给目标本人。原申请获批执行后生效；页面刷新或退出后无法找回。请勿放入聊天、截图、日志或文档。'));const input=node('input');input.value=value;input.readOnly=true;input.type='password';input.setAttribute('aria-label','一次性交付码');body.append(input);const show=button('显示或隐藏交付码',()=>{input.type=input.type==='password'?'text':'password';});body.append(show);const link=node('a','text-link','打开本人设置页');link.href='/account-setup';body.append(link);$('#dialog-actions').append(button('关闭',closeWork,'plain'));}
function openAccountMaintenance(p){const body=openWork('账号与验证器维护','目标 '+p.personId);body.append(node('p','notice','方案由当前策略多人审批。正常换绑还需本人旧MFA；恢复会删除未保留的旧绑定。首次绑定或重设密码只由本人完成，不在管理平台输入密码或种子。'));const form=node('form','form-grid');form.id='account-maintenance';const mode=node('select');mode.name='mode';mode.setAttribute('aria-label','维护类型');for(const [value,title]of [['bind','正常绑定／换绑'],['enroll','首次绑定'],['recover','丢失恢复'],['account_state','本地账号启停／解锁']]){const option=node('option','',title);option.value=value;option.disabled=value==='bind'&&!p.mfaConfigured||value==='enroll'&&p.mfaConfigured||value==='account_state'&&!p.account;mode.append(option);}mode.value=p.mfaConfigured?'bind':'enroll';form.append(mode);const fields=node('div','full');form.append(fields);
 const draw=()=>{fields.replaceChildren();if(mode.value==='account_state'){const label=node('label','','本地账号状态');const enabled=node('select');enabled.name='enabled';for(const [value,title]of [['true','启用'],['false','停用']]){const option=node('option','',title);option.value=value;enabled.append(option);}enabled.value=String(p.account.enabled);label.append(enabled);const unlock=node('label','','解除失败锁定');const check=node('input');check.type='checkbox';check.name='unlock';unlock.append(check);fields.append(label,unlock);return;}
 const password=node('label','','由本人设置新密码（首次创建本地账号或密码丢失）');const reset=node('input');reset.type='checkbox';reset.name='resetPassword';password.append(reset);const username=node('input');username.name='username';username.placeholder='本地登录账号名';username.maxLength=128;username.value=p.account?.username||'';username.readOnly=!!p.account;fields.append(password,username);
 const keep=node('div');keep.append(node('h3','','保留的旧验证器'));for(const factor of p.factors||[]){const label=node('label','',factor.label+' · '+labels.methods[factor.method]);const check=node('input');check.type='checkbox';check.name='keep';check.value=factor.id;check.checked=mode.value==='bind';check.disabled=mode.value==='recover'||mode.value==='enroll';label.prepend(check);keep.append(label);}fields.append(keep);
 const top=node('label','','至少通过几种方式');const m=node('input');m.type='number';m.name='m';m.min=1;m.max=4;m.required=true;m.value=mode.value==='bind'?p.policy?.m||1:1;top.append(m);fields.append(top);for(const method of ['totp','email','sms','hardware']){const old=mode.value==='bind'?p.policy?.rules.find(r=>r.method===method):null;const row=node('div','form-grid');const enabled=node('input');enabled.type='checkbox';enabled.name=method+'Enabled';enabled.checked=!!old||(mode.value!=='bind'&&method==='totp');const label=node('label','',labels.methods[method]);label.prepend(enabled);row.append(label);for(const [suffix,title,value]of [['M','此方式至少完成',old?.m||1],['N','此方式绑定总数',old?.n||1]]){const field=node('label','',title),input=node('input');input.type='number';input.name=method+suffix;input.min=1;input.max=16;input.value=value;field.append(input);row.append(field);}const required=node('label','','此方式必需');const check=node('input');check.type='checkbox';check.name=method+'Required';check.checked=!!old?.required;required.prepend(check);row.append(required);fields.append(row);}}
 mode.addEventListener('change',draw);draw();governanceEvidence(form);body.append(form);const raw=new Uint8Array(32);crypto.getRandomValues(raw);const code=btoa(String.fromCharCode(...raw)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');const submit=operationSubmitter(),identityEpoch=state.identityGeneration;formAction(form,'提交账号与验证器审批',async d=>{const maintenance={target:p.principalId,mode:d.get('mode'),resetPassword:false,enabled:false,unlock:false,reason:d.get('reason').trim(),evidenceHash:d.get('evidenceHash').trim()};if(maintenance.mode==='account_state'){maintenance.enabled=d.get('enabled')==='true';maintenance.unlock=d.has('unlock');}else{maintenance.tokenHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(code))),b=>b.toString(16).padStart(2,'0')).join('');maintenance.resetPassword=d.has('resetPassword');if(maintenance.resetPassword)maintenance.username=d.get('username').trim();maintenance.keep=d.getAll('keep');if(p.policy)maintenance.previousPolicy=p.policy;maintenance.policy={m:Number(d.get('m')),rules:['totp','email','sms','hardware'].filter(method=>d.has(method+'Enabled')).map(method=>({method,m:Number(d.get(method+'M')),n:Number(d.get(method+'N')),required:d.has(method+'Required')}))};}const request=await submit({kind:'account_maintenance',clientId:'governance-management',expectedRevision:p.revision,name:'',profileId:'',profileVersion:'0',maintenance});if(identityEpoch!==state.identityGeneration||!state.session)return;if(maintenance.mode!=='account_state'){state.maintenanceCodes.set(request.id,code);openMaintenanceCode(request.id);}});}

function canWithdraw(r){return !r.executed&&!r.invalidated&&['pending','approved'].includes(requestState(r))&&manifest(r).applicant.principalId===state.session?.principalId&&hasRole('requester')&&state.context?.identity?.mfaVerified;}
function openWithdraw(r){const body=openWork('撤回申请','审批中心');body.append(node('p','notice danger','撤回后保留历史投票与审计，本申请不能再审批或执行。已执行的操作不能撤回；请勿在原因中填写密码、验证码或恢复码。'));const form=node('form');form.id='withdraw-request';const label=node('label','','撤回原因'),reason=node('textarea');reason.name='reason';reason.required=true;reason.maxLength=500;label.append(reason);const confirm=node('label','','我确认撤回这份申请');const check=node('input');check.type='checkbox';check.required=true;confirm.prepend(check);form.append(label,confirm);body.append(form);const generation=state.identityGeneration;formAction(form,'确认撤回申请',async data=>{const reason=data.get('reason').trim();const size=new TextEncoder().encode(reason).length;if(size<3||size>500)throw new Error('撤回原因须为3至500个UTF-8字节。');await api('/api/requests/'+encodeURIComponent(r.id)+'/withdraw','POST',{digest:r.digest,reason});if(generation!==state.identityGeneration)return;closeWork();state.verified.delete(r.id);state.maintenanceCodes.delete(r.id);toast('申请已撤回，历史记录已保留。');await refresh();});}
function renderNotifications(){const target=$('#notification-table');if(!state.notifications){empty(target,'暂无可读取的通知',state.session?'完成本人验证后刷新。':'请先登录。');$('#notification-count').textContent='';return;}const unread=state.notifications.filter(n=>!n.read).length;$('#notification-count').textContent=unread?unread+' 条未读':'';const records=state.notifications.filter(n=>!$('#notice-unread-only').checked||!n.read);const kinds={approval_turn:'轮到本人审批',approval_ready:'已批准，等待本人执行',approval_rejected:'申请已拒绝',approval_withdrawn:'申请已撤回',approval_executed:'申请已执行',approval_due:'申请将在1分钟内到期',approval_expired:'申请已超时',approval_invalidated:'申请资格或策略已失效'};const delivery={pending:'等待插件投递',sending:'投递中',sent:'插件已确认接收',obsolete:'提醒已失效',failed:'投递未确认，重试已达上限'};if(!records.length){empty(target,'暂无通知','审批交接、即将到期和结果会显示在这里。');return;}table(target,['通知','申请','时间','外部投递','操作'],records.map(n=>{const actions=node('div','table-actions');actions.append(button('查看申请',async()=>{const generation=state.identityGeneration;await api('/api/notifications/'+n.id+'/read','POST',{});if(generation!==state.identityGeneration)return;await refresh();if(generation===state.identityGeneration)await openRequest(n.requestId);},'text-button'));if(!n.read)actions.append(button('标为已读',async()=>{await api('/api/notifications/'+n.id+'/read','POST',{});await refresh();},'text-button'));return[textCell(kinds[n.kind]||n.kind,n.read?'已读':'未读'),short(n.requestId),fullDate(n.createdAt),delivery[n.state]||n.state,actions];}));}
$('#notice-unread-only').addEventListener('change',renderNotifications);

// 全域运维数据与个人收件箱分开，身份或本人验证失效时立即清空缓存与DOM。
function renderNotificationOpsVisibility(){const own=state.context?.identity;const allowed=!!own?.mfaVerified&&own.grants.some(g=>!g.clientId&&['policy_admin','auditor'].includes(g.role));const d=$('#work-dialog'),canWrite=!!own?.mfaVerified&&own.grants.some(g=>!g.clientId&&g.role==='policy_admin');if(d.dataset.notificationOps&&(!allowed||(d.dataset.notificationOps==='write'&&!canWrite))){closeWork();$('#dialog-body').replaceChildren();$('#dialog-actions').replaceChildren();notice($('#dialog-error'),'');delete d.dataset.notificationOps;}$('#notification-operations').hidden=!allowed;if(!allowed){state.noticeOps=null;state.notificationOffset=0;for(const id of ['notification-alerts','notification-ops-table','notification-ops-footer'])$('#'+id).replaceChildren();}}
async function loadNotificationOps(){const generation=state.identityGeneration,epoch=state.epoch,offset=state.notificationOffset,filter=$('#notification-state').value;const result=await api('/api/notification-operations?state='+encodeURIComponent(filter)+'&offset='+offset);if(generation!==state.identityGeneration||epoch!==state.epoch||offset!==state.notificationOffset||filter!==$('#notification-state').value)return;state.noticeOps=result;renderNotificationOperations();}
const notificationStateLabels={pending:'等待投递',sending:'投递中',sent:'已确认接收',obsolete:'已失效',failed:'失败'};
function renderNotificationOperations(){const data=state.noticeOps;if(!data)return;const alerts=$('#notification-alerts');alerts.replaceChildren();const names={backlog:'投递积压',failed:'存在失败任务',stale_lease:'发送租约超时'};for(const a of data.alerts){const row=node('div',a.active?'notice warning':'form-note');row.append(document.createTextNode((names[a.code]||a.code)+'：'+(a.active?'告警':'正常')+' · '+a.count+' 条'+(a.code==='backlog'?' · 最老等待 '+a.oldestSeconds+' 秒':'')+' · 检查于 '+fullDate(a.checkedAt)));alerts.append(row);}if(!data.alerts.length)alerts.append(node('span','subtle','等待后台首次检查。'));const target=$('#notification-ops-table');if(!data.items.length)empty(target,'暂无此状态的任务','');else table(target,['申请 / 通知','收件人','状态','本轮尝试 / 人工重发','创建时间','操作'],data.items.map(n=>{const actions=node('div','table-actions');actions.append(button('投递记录',()=>openDeliveryRecords(n),'text-button'));if(data.canResend&&n.state==='failed'&&n.resends<3)actions.append(button('受控重发',()=>openNotificationResend(n),'text-button'));return [textCell(short(n.requestId),short(n.id)),person(n.recipientId),notificationStateLabels[n.state]||n.state,n.attempts+' / '+n.resends,fullDate(n.createdAt),actions];}));const footer=$('#notification-ops-footer');footer.replaceChildren(node('span','', '每页50条；最多查询前10050条，刷新后按当前状态重新排序。'));const prev=button('上一页',async()=>{state.notificationOffset=Math.max(0,state.notificationOffset-50);await loadNotificationOps();});prev.disabled=state.notificationOffset===0;const next=button('下一页',async()=>{state.notificationOffset+=50;await loadNotificationOps();});next.disabled=!data.more||state.notificationOffset>=10000;footer.append(prev,node('span','',String(state.notificationOffset/50+1)),next);}
async function openDeliveryRecords(n){const generation=state.identityGeneration,epoch=state.epoch,ticket=++state.dialogEpoch;const rows=await api('/api/notification-operations/'+n.id+'/records');if(generation!==state.identityGeneration||epoch!==state.epoch||ticket!==state.dialogEpoch||$('#notification-operations').hidden)return;const body=openWork('投递记录',short(n.id),true);$('#work-dialog').dataset.notificationOps='read';body.append(node('p','form-note','旧版本未保存的逐次记录不补造。确认接收不等于用户已读；租约超时的结果可能未知。'));const target=node('div');body.append(target);const outcomes={sending:'发送中',sent:'插件确认接收',unconfirmed:'未确认接收',lease_expired:'租约超时，结果未确认',obsolete:'通知已失效',rescheduled:'人工重排'};if(!rows.length)empty(target,'暂无逐次记录','');else table(target,['轮次 / 尝试','开始时间','完成时间','结果','操作人 / 原因'],rows.map(r=>[r.round+' / '+r.attempt,fullDate(r.startedAt),fullDate(r.finishedAt),outcomes[r.outcome]||r.outcome,textCell(r.actorId?person(r.actorId):'系统',r.reason)]));}
function openNotificationResend(n){const body=openWork('受控重发','通知运维');$('#work-dialog').dataset.notificationOps='write';body.append(node('p','notice warning','仅重排仍有效的失败通知，每轮最多5次、人工最多3轮，两轮间隔至少60秒。未确认的旧投递可能已到达，插件须去重。'));const form=node('form');form.id='notification-resend';const label=node('label','','重发原因'),reason=node('textarea');reason.name='reason';reason.required=true;reason.maxLength=500;label.append(reason);const confirm=node('label','check-row','确认重排原通知');const check=node('input');check.type='checkbox';check.required=true;confirm.prepend(check);form.append(label,confirm);body.append(form);const generation=state.identityGeneration;formAction(form,'确认重发',async d=>{const reason=d.get('reason').trim(),size=new TextEncoder().encode(reason).length;if(size<3||size>500)throw new Error('原因须为3至500个UTF-8字节。');await api('/api/notification-operations/'+n.id+'/resend','POST',{digest:n.digest,expectedRound:n.resends,reason});if(generation!==state.identityGeneration)return;closeWork();toast('已重排投递。');await loadNotificationOps();});}
$('#load-notification-ops').addEventListener('click',()=>busy($('#load-notification-ops'),loadNotificationOps));$('#notification-state').addEventListener('change',()=>{state.notificationOffset=0;loadNotificationOps().catch(showError);});
